
.controller.ds4 {
  background: url("data:image/svg+xml;base64,");
  height: 598px;
  width: 806px;
  
}

.ds4.disconnected {
  background: url("data:image/svg+xml;base64,");
}

.ds4.disconnected div {
  display: none;
}

.ds4 .triggers {
  width: 588px;
  height: 90px;
  position: absolute;
  left: 109px;
}

.ds4 .trigger {
  width: 99px;
  height: 100%;
  background: url("data:image/svg+xml;base64,");
  opacity: 0;
}

.ds4 .trigger.left {
  float: left;
}

.ds4 .trigger.right {
  float: right;
  background-position-x: 99px;
}

.ds4 .bumper {
  width: 99px;
  height: 23px;
  background: url("data:image/svg+xml;base64,") no-repeat;
  opacity: 0;
}

.ds4 .bumpers {
  position: absolute;
  width: 588px;
  height: 23px;
  left: 109px;
  top: 94px;
}

.ds4 .bumper.pressed {
  opacity: 1;
}

.ds4 .bumper.left {
  
  
  float: left;
}

.ds4 .bumper.right {
  float: right;
  transform: rotateY(180deg);
}

.ds4 .touchpad {
  width: 262px;
  height: 151px;
  position: absolute;
  left: 272px;
  top: 122px;
}

.ds4 .touchpad.pressed {
  background: url("data:image/svg+xml;base64,") no-repeat center;
}

.ds4 .meta {
  width: 42px;
  height: 42px;
  position: absolute;
  left: 382px;
  bottom: 216px;
}

.ds4 .meta.pressed {
  background: url("data:image/svg+xml;base64,") no-repeat center;
}



.ds4 .arrows {
  position: absolute;
  width: 352px;
  height: 46px;
  top: 142px;
  left: 227px;
}

.ds4 .back,
.ds4 .start {
  background: url("data:image/svg+xml;base64,");
  width: 28px;
  height: 46px;
  opacity: 0;
}

.ds4 .back.pressed,
.ds4 .start.pressed {
  
  
  opacity: 1;
}

.ds4 .back {
  float: left;
  
}

.ds4 .start {
  float: right;
  
  background-position: 28px 0;
}

.ds4 .abxy {
  position: absolute;
  width: 170px;
  height: 171px;
  top: 159px;
  left: 567px;
}

.ds4 .button {
  position: absolute;
  width: 55px;
  height: 55px;
  background: url("data:image/png;base64,");
}

.ds4 .button.pressed {
  background-position-y: 55px;
  
}

.ds4 .a {
  background-position: 0 0;
  bottom: 0;
  left: 58px;
}

.ds4 .b {
  background-position: -57px 0;
  top: 58px;
  right: 0px;
}

.ds4 .x {
  background-position: -113px 0;
  top: 58px;
}

.ds4 .y {
  background-position: 55px 0;
  left: 58px;
}

.ds4 .sticks {
  position: absolute;
  width: 361px;
  height: 105px;
  top: 308px;
  left: 228px;
}

.ds4 .stick {
  position: absolute;
  background: url("data:image/png;base64,");
  height: 94px;
  width: 94px;
}

.ds4 .stick.pressed.left {
  background-position-x: -96px;
}

.ds4 .stick.pressed.right {
  background-position-x: -192px;
}

.ds4 .stick.left {
  top: 0;
  left: 0;
}

.ds4 .stick.right {
  top: calc(100% - 105px);
  left: calc(100% - 105px);
}

.ds4 .dpad {
  position: absolute;
  width: 125px;
  height: 126px;
  top: 181px;
  left: 92px;
}

.ds4 .face {
  background: url("data:image/png;base64,");
  position: absolute;
}

.ds4 .face.up,
.ds4 .face.down {
  width: 36px;
  height: 52px;
}

.ds4 .face.left,
.ds4 .face.right {
  width: 52px;
  height: 36px;
}

.ds4 .face.up {
  left: 44px;
  top: 0;
  background-position: -37px 0px;
}

.ds4 .face.down {
  left: 44px;
  bottom: 0;
  background-position: 0px 0;
}

.ds4 .face.left {
  top: 45px;
  left: 0;
  background-position: 104px 0;
}

.ds4 .face.right {
  top: 45px;
  right: 0px;
  background-position: 52px 0;
}

.ds4 .face.pressed {
  
  background-position-y: 52px;
}

.ds4.half {
  margin-top: -300px;
}



/* Omen Reapers: local sprites and stable PS4 placement. */
.controller.ds4 {height:599px;background-repeat:no-repeat;background-size:806px 599px;}
.ds4 .triggers {top:0;}
.ds4 .button {background-size:224px 112px;}
.ds4 .button.pressed {background-position-y:-56px;}
.ds4 .face {background-size:179px 104px;}
.ds4 .face.pressed {background-position-y:-52px;}
.ds4 .face.left {background-position-x:-75px;}
.ds4 .face.right {background-position-x:-127px;}
.ds4 .start {background-position:0 0;}
.ds4 .stick {background-color:transparent;-webkit-mask:none;mask:none;}
.ds4.disconnected {opacity:.4;}
